contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint m, uint a) public {
        require(m > 0);
        require(a > 0);
        c.SetMinSum(m);
        uint minSumBefore = c.MinSum();
        uint balBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;
        bool reverted;
        try c.Collect(a) { reverted = false; } catch { reverted = true; }
        assert(!reverted && c.MinSum() == minSumBefore && minSumBefore == m
            && c.balances(address(this)) == balBefore && balBefore == 0
            && address(c).balance == ethBefore && ethBefore == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint m, uint d, uint a) public {
        require(m > 0);
        require(d >= m);
        require(a > 0);
        c.SetMinSum(m);
        c.Initialized();
        c.Deposit{value: d}();
        uint balBefore = c.balances(address(this));
        uint minSumBefore = c.MinSum();
        bool reverted;
        try c.Collect(a) { reverted = false; } catch { reverted = true; }
        assert((!reverted && balBefore == d && c.balances(address(this)) == d - a && c.MinSum() == m && c.MinSum() == minSumBefore)
            || (reverted && a > balBefore && c.balances(address(this)) == balBefore && minSumBefore == m));
    }
    receive() external payable {}
}

